import type { Acl } from '../app';
/**
 * Resolver for one or more GraphQL schema fields (`sys_graphql_resolver`).
 * @interface
 */
export type GraphQLResolver = Now.Internal.WithID<{
    /** Identifier for the resolver, unique within the schema. The `paths` it serves point back to this name. */
    name: string;
    /** Server script that resolves the field value. Use a server module function, inline string, or `Now.include('./resolver.js')` to keep it in a separate file. For fields with arguments, read them with `env.getArguments()`. */
    script: ((env: any) => unknown) | string;
    /** Schema fields this resolver serves, each in `Type:field` form (for example `Query:hello`). One resolver mapping (`sys_graphql_resolver_mapping`) is created per path. */
    paths: string[];
} & Now.Internal.Meta>;
/**
 * Resolver that selects the concrete type for a GraphQL union or interface (`sys_graphql_typeresolver`).
 * @interface
 */
export type GraphQLTypeResolver = Now.Internal.WithID<{
    /** Name of the union or interface type in the SDL this resolver applies to. */
    typeName: string;
    /** Server script that returns the concrete type name. Use a server module function, inline string, or `Now.include('./typeResolver.js')` to keep it in a separate file. */
    script: ((env: any) => unknown) | string;
} & Now.Internal.Meta>;
/** @interface */
export type GraphQLApi = Now.Internal.WithIdAndMetadata<{
    /** The name of the GraphQL API. */
    name: string;
    /** The top-level namespace in the query envelope, as in `{ xSncMyApp { myApi { ... } } }`. Derived from the application scope; only honored in global scope, where it falls back to `now`. Must be a valid GraphQL name, 40 characters or fewer. */
    applicationNamespace?: string;
    /** The API namespace used in the query envelope and in runtime ACL paths (for example `myApi` in `{ xSncMyApp { myApi { ... } } }`). Must be a valid GraphQL name, unique among the APIs in its application namespace. */
    namespace: string;
    /** The schema definition language (SDL) for the API. Inline, or `Now.include('./schema.graphql')`. The platform compiles it on insert. */
    schema: string;
    /** Resolvers that fetch field data, each bound to one or more schema paths. */
    resolvers?: GraphQLResolver[];
    /** Type resolvers for the unions and interfaces in the schema. */
    typeResolvers?: GraphQLTypeResolver[];
    /** Indicates whether the API can serve requests. Defaults to true. */
    active?: boolean;
    /** Schema-gate ACLs (`sys_security_acl`) that control access to the whole API. Accepts ACL `sys_id`s or `Acl` references. Field-level path ACLs are standalone `Acl({ type: 'graphql' })` records, not set here. */
    enforceAcl?: (string | ReturnType<typeof Acl>)[];
    /** If true, callers must be authenticated. Defaults to true. */
    requiresAuthentication?: boolean;
    /** If true, the schema-gate ACLs in `enforceAcl` are enforced. Defaults to true. */
    requiresAclAuthorization?: boolean;
    /** If true, callers must hold the `snc_internal` role. Defaults to true. */
    requiresSncInternalRole?: boolean;
    /** The maximum path depth at which field-level path ACLs are enforced. Depth counts every segment of the ACL path, including the two envelope segments, so `/xSncMyApp/myApi/items/cost` is depth 4. Defaults to 4, which covers top-level and second-level fields. */
    contextualAclMaxDepth?: number;
}>;
